let sql = $json.sql?.trim() || "";
let explanation = $json.explanation || "";

// Case 1: LLM refused / did not generate SQL
if (!sql) {
  return [{
    json: {
      valid: false,
      type: "no_sql",
      reason: explanation || "No SQL query generated.",
      sql
    }
  }];
}

// Continue validation only when SQL exists
const upperSql = sql.toUpperCase();

const forbidden = [
  "INSERT",
  "UPDATE",
  "DELETE",
  "DROP",
  "ALTER",
  "CREATE",
  "TRUNCATE",
  "GRANT",
  "REVOKE",
  "COPY",
  "EXECUTE",
  "DO"
];

// Must start with SELECT
if (!upperSql.startsWith("SELECT")) {
  return [{
    json: {
      valid: false,
      type: "invalid_sql",
      reason: "Only SELECT queries are allowed.",
      sql
    }
  }];
}

// Reject multiple statements
const semicolons = (sql.match(/;/g) || []).length;

if (semicolons > 1) {
  return [{
    json: {
      valid: false,
      type: "invalid_sql",
      reason: "Multiple SQL statements are not allowed.",
      sql
    }
  }];
}

// Forbidden keywords
for (const keyword of forbidden) {
  const regex = new RegExp(`\\b${keyword}\\b`, "i");

  if (regex.test(sql)) {
    return [{
      json: {
        valid: false,
        type: "invalid_sql",
        reason: `Forbidden keyword detected: ${keyword}`,
        sql
      }
    }];
  }
}

// Passed
return [{
  json: {
    valid: true,
    type: "valid_sql",
    reason: "",
    sql
  }
}];

const tables = [
  ...new Set(
    $input.all().map(item => item.json["Table Name"])
  )
]
.map(table => `'${table}'`)
.join(",");

return [
  {
    json: {
      tables
    }
  }
];

const sheet = $('Load Table Definitions').all();
const schema = $('Load Database Schema').all();

const result = {};

// Step 1: Build table metadata from Google Sheet
for (const item of sheet) {
  const row = item.json;
  const table = row["Table Name"];

  // Create table only once
  if (!result[table]) {
    result[table] = {
      description: row["Description"],
      primary_key: row["Primary key"],
      schema: []
    };
  }
}

// Step 2: Add columns from database schema
for (const item of schema) {
  const row = item.json;
  const table = row.table_name;

  if (!result[table]) continue;

  result[table].schema.push({
    name: row.column_name,
    type: row.data_type,
    is_primary_key: row.is_primary_key,
    referenced_table: row.referenced_table,
    referenced_column: row.referenced_column,
    enum_values: row.enum_values
  });
}

return [{
  json: result
}];

